// that returns the class-N (positive-class) probability.
static double siren_tag_score_class_0(double * input) {
    double _out[2] = {0.0, 0.0};
    siren_tag_class_0_impl(input, _out);
    return _out[1];  // P(label=1) = class-0 probability
}

